import { useState, useEffect } from "react";
import { getAllSubmissions, getDashboardStats } from "./kycApi";
import { kycRequests as mockData } from "../data/mockData";

// Maps backend KYC record → portal format
function mapKycRecord(r) {
  return {
    id:            r._id || r.id || r.userId,
    name:          r.name || r.userName || r.user?.name || "Unknown",
    initials:      (r.name || r.userName || "?").split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase(),
    color:         "#6C63FF",
    submitted:     r.submittedAt ? new Date(r.submittedAt).toLocaleString("en-IN", { day:"2-digit", month:"short", hour:"2-digit", minute:"2-digit" }) : "—",
    status:        mapStatus(r.status || r.kycStatus),
    email:         r.email || r.user?.email || "—",
    phone:         r.mobile || r.phone || r.user?.mobile || "—",
    dob:           r.dob || "—",
    address:       r.address || "—",
    rejectionReason: r.rejectionReason || r.reason || "",
    documents: {
      aadhaar:  { submitted: !!(r.aadharFront || r.aadhaarUrl),  number: r.aadharNumber  || "XXXX XXXX XXXX", name: r.name || "—", dob: r.dob || "—", address: r.address || "—" },
      pan:      { submitted: !!(r.panCard || r.panUrl),           number: r.panNumber     || "—",              name: r.name || "—", dob: r.dob || "—" },
      passport: { submitted: !!(r.passport || r.passportUrl),     number: r.passportNumber|| "—",              name: r.name || "—", expiry: r.passportExpiry || "—", country: "India" },
      selfie:   { submitted: !!(r.selfie || r.selfieUrl) },
    },
  };
}

function mapStatus(status) {
  const map = {
    under_review:       "In Review",
    approved:           "Approved",
    rejected:           "Failed",
    documents_uploaded: "Pending",
    not_started:        "Pending",
  };
  return map[status] || "Pending";
}

export function useKycData() {
  const [data, setData]           = useState(mockData);
  const [stats, setStats]         = useState(null);
  const [loading, setLoading]     = useState(true);
  const [usingMock, setUsingMock] = useState(false);
  const [error, setError]         = useState(null);

  const fetchData = () => {
    setLoading(true);
    Promise.all([
      getAllSubmissions({ page: 1, limit: 100 }),
      getDashboardStats(),
    ])
      .then(([subRes, statsRes]) => {
        // Map backend records to portal format
        const raw = subRes.data?.submissions
          || subRes.data?.kyc
          || subRes.data?.data
          || subRes.data
          || [];
        const mapped = Array.isArray(raw) ? raw.map(mapKycRecord) : mockData;
        setData(mapped.length > 0 ? mapped : mockData);
        setStats(statsRes.data);
        setUsingMock(false);
        setError(null);
      })
      .catch((err) => {
        // Backend not reachable or admin endpoint missing → use mock
        setData(mockData);
        setUsingMock(true);
        setError(err?.response?.data?.message || "Backend not reachable — showing demo data");
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchData(); }, []);

  return { data, setData, stats, loading, usingMock, error, refetch: fetchData };
}

export function useWalletData() {
  // Placeholder — wallet data comes from /api/wallet/* endpoints
  // Wired when admin wallet management endpoints are available
  return { wallets: [], loading: false, usingMock: true };
}
